-- 迁移 096：教育部科研统计任务、版本、数据包导入/校验、调整留痕和导出任务。
-- 仅保存用户提供的数据包和校验事实；不会伪造教育部回执或统计数据。
BEGIN;

CREATE TABLE IF NOT EXISTS "教育部统计任务" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "统计年度" integer NOT NULL,
    "任务代码" varchar(100) NOT NULL,
    "任务名称" varchar(200) NOT NULL,
    "截止日期" date,
    "数据截止日期" date,
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "当前版本编号" bigint,
    "说明" varchar(2000),
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_教育部统计任务" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_教育部统计任务_代码" UNIQUE ("统计年度", "任务代码"),
    CONSTRAINT "ck_教育部统计任务_年度" CHECK ("统计年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_教育部统计任务_状态" CHECK ("状态" IN ('草稿','开放','导入中','校验中','待调整','可导出','已导出','已关闭','失败'))
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计任务_年度状态" ON "教育部统计任务" ("统计年度" DESC, "状态");

CREATE TABLE IF NOT EXISTS "教育部统计版本" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "任务编号" bigint NOT NULL REFERENCES "教育部统计任务"("编号") ON DELETE CASCADE,
    "版本号" integer NOT NULL,
    "模板代码" varchar(100) NOT NULL,
    "模板名称" varchar(200) NOT NULL,
    "字段定义" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "变更说明" varchar(2000),
    "创建人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_教育部统计版本" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_教育部统计版本_任务版本" UNIQUE ("任务编号", "版本号"),
    CONSTRAINT "ck_教育部统计版本_版本号" CHECK ("版本号" > 0),
    CONSTRAINT "ck_教育部统计版本_状态" CHECK ("状态" IN ('草稿','生效','停用')),
    CONSTRAINT "ck_教育部统计版本_字段定义" CHECK (jsonb_typeof("字段定义") = 'array')
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计版本_任务状态" ON "教育部统计版本" ("任务编号", "状态", "版本号" DESC);
ALTER TABLE "教育部统计任务"
    ADD CONSTRAINT "fk_教育部统计任务_当前版本"
    FOREIGN KEY ("当前版本编号") REFERENCES "教育部统计版本"("编号") DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE IF NOT EXISTS "教育部统计数据包" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "任务编号" bigint NOT NULL REFERENCES "教育部统计任务"("编号") ON DELETE CASCADE,
    "版本编号" bigint NOT NULL REFERENCES "教育部统计版本"("编号"),
    "包名称" varchar(300) NOT NULL,
    "文件类型" varchar(100),
    "文件路径" varchar(1000),
    "文件校验和" varchar(128),
    "原始内容" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "状态" varchar(20) NOT NULL DEFAULT '待导入',
    "记录数" integer NOT NULL DEFAULT 0,
    "校验错误数" integer NOT NULL DEFAULT 0,
    "校验警告数" integer NOT NULL DEFAULT 0,
    "导入人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "导入时间" timestamp without time zone,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "说明" varchar(2000),
    CONSTRAINT "pk_教育部统计数据包" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_教育部统计数据包_状态" CHECK ("状态" IN ('待导入','待校验','校验中','校验通过','校验失败','已作废')),
    CONSTRAINT "ck_教育部统计数据包_数量" CHECK ("记录数" >= 0 AND "校验错误数" >= 0 AND "校验警告数" >= 0),
    CONSTRAINT "ck_教育部统计数据包_内容" CHECK (jsonb_typeof("原始内容") = 'array')
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计数据包_任务状态" ON "教育部统计数据包" ("任务编号", "状态", "更新时间" DESC);

CREATE TABLE IF NOT EXISTS "教育部统计字段校验" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "数据包编号" bigint NOT NULL REFERENCES "教育部统计数据包"("编号") ON DELETE CASCADE,
    "记录序号" integer NOT NULL,
    "记录标识" varchar(200),
    "字段代码" varchar(100),
    "严重程度" varchar(10) NOT NULL,
    "消息" varchar(2000) NOT NULL,
    "实际值" varchar(4000),
    "状态" varchar(20) NOT NULL DEFAULT '未处理',
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "处理人编号" integer REFERENCES "人员"("编号"),
    "处理时间" timestamp without time zone,
    CONSTRAINT "pk_教育部统计字段校验" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_教育部统计字段校验_严重程度" CHECK ("严重程度" IN ('错误','警告')),
    CONSTRAINT "ck_教育部统计字段校验_状态" CHECK ("状态" IN ('未处理','已修正','已接受'))
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计字段校验_数据包" ON "教育部统计字段校验" ("数据包编号", "严重程度", "记录序号");

CREATE TABLE IF NOT EXISTS "教育部统计调整留痕" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "数据包编号" bigint NOT NULL REFERENCES "教育部统计数据包"("编号") ON DELETE CASCADE,
    "记录序号" integer NOT NULL,
    "记录标识" varchar(200),
    "字段代码" varchar(100) NOT NULL,
    "原值" jsonb,
    "新值" jsonb,
    "调整原因" varchar(2000) NOT NULL,
    "调整人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "请求编号" varchar(100),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_教育部统计调整留痕" PRIMARY KEY ("编号")
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计调整留痕_数据包" ON "教育部统计调整留痕" ("数据包编号", "创建时间" DESC);

CREATE TABLE IF NOT EXISTS "教育部统计导出任务" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "任务编号" bigint NOT NULL REFERENCES "教育部统计任务"("编号") ON DELETE CASCADE,
    "版本编号" bigint NOT NULL REFERENCES "教育部统计版本"("编号"),
    "数据包编号" bigint REFERENCES "教育部统计数据包"("编号"),
    "导出格式" varchar(20) NOT NULL DEFAULT 'xlsx',
    "状态" varchar(20) NOT NULL DEFAULT '申请中',
    "文件路径" varchar(1000),
    "文件校验和" varchar(128),
    "记录数" integer,
    "错误信息" varchar(4000),
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "完成时间" timestamp without time zone,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_教育部统计导出任务" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_教育部统计导出任务_格式" CHECK ("导出格式" IN ('xlsx','csv','xml')),
    CONSTRAINT "ck_教育部统计导出任务_状态" CHECK ("状态" IN ('申请中','生成中','已完成','失败','已取消')),
    CONSTRAINT "ck_教育部统计导出任务_记录数" CHECK ("记录数" IS NULL OR "记录数" >= 0)
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计导出任务_任务状态" ON "教育部统计导出任务" ("任务编号", "状态", "申请时间" DESC);

CREATE TABLE IF NOT EXISTS "教育部统计操作审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "任务编号" bigint REFERENCES "教育部统计任务"("编号") ON DELETE SET NULL,
    "版本编号" bigint REFERENCES "教育部统计版本"("编号") ON DELETE SET NULL,
    "数据包编号" bigint REFERENCES "教育部统计数据包"("编号") ON DELETE SET NULL,
    "导出任务编号" bigint REFERENCES "教育部统计导出任务"("编号") ON DELETE SET NULL,
    "操作类型" varchar(50) NOT NULL,
    "操作人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "说明" varchar(2000),
    "请求编号" varchar(100),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_教育部统计操作审计" PRIMARY KEY ("编号")
);
CREATE INDEX IF NOT EXISTS "ix_教育部统计操作审计_时间" ON "教育部统计操作审计" ("创建时间" DESC, "操作类型");

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (207, 2, '教育部科研统计', '科研办公/科研办公/教育部科研统计.html', TRUE,
        '教育部统计任务、版本、数据包校验、调整留痕和导出任务')
ON CONFLICT ("编号") DO UPDATE SET "上级编号"=EXCLUDED."上级编号", "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "类型"=EXCLUDED."类型", "备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 207 FROM "角色" r
 WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
   AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=207);

UPDATE "系统迁移版本"
   SET "版本"=96, "脚本"='096_ministry_statistics_package.sql',
       "检查摘要"='教育部统计任务与版本、数据包导入/字段校验、调整留痕和导出任务', "应用时间"=CURRENT_TIMESTAMP
 WHERE "编号"=1;

COMMIT;
